import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException


class ConfirmationModal(object):
    MODAL_XPATH = '//div[@class="modal-content"]'
    CONFIRM_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Confirm"]/button'

    def __init__(self, tool):
        self._tool = tool

    def confirm(self):
        """
        Clicks confirm button in selenium_coam confirmation modal
        """
        pass

    def wait_until_modal_appear(self, locator, timeout=60):
        self._tool.wait_for_visibility(locator, timeout)


class LegalNoticeModal(ConfirmationModal):

    def __init__(self, tool):
        super(LegalNoticeModal, self).__init__(tool)

    def wait_until_legal_notice_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self.MODAL_XPATH), timeout)

    def confirm(self, timeout=60):
        self._tool.click_enabled_element((By.XPATH, self.CONFIRM_BUTTON_XPATH), timeout)


class ResetModal(ConfirmationModal):
    MODAL_RESET_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[contains(@a-text, "Reset")]'

    def __init__(self, tool):
        super(ResetModal, self).__init__(tool)

    def wait_until_reset_modal_appear(self, timeout=60):
        try:
            self.wait_until_modal_appear((By.XPATH, self.MODAL_XPATH), timeout)
        except TimeoutException:
            logging.warning("No reset modal is found")

    def confirm(self):
        self._tool.click_enabled_element((By.XPATH, self.MODAL_RESET_BUTTON_XPATH))


class RollbackSoftwareModal(ConfirmationModal):
    MODAL_ROLLBACK_BUTTON_XPATH = "//div[@class='modal-content']//button[contains(text(), 'Rollback')]"

    def __init__(self, tool):
        super(RollbackSoftwareModal, self).__init__(tool)

    def wait_until_rollback_software_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self.MODAL_XPATH), timeout)

    def confirm(self, timeout=60):
        self._tool.click_enabled_element((By.XPATH, self.MODAL_ROLLBACK_BUTTON_XPATH), timeout)


class BtsStartUpViewModal(ConfirmationModal):
    _MODAL_XPATH = '//div[@class="modal-content"]//ui-modal[@*="BTS Start-up View"]'
    _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'

    def __init__(self, tool):
        super(BtsStartUpViewModal, self).__init__(tool)

    def wait_for_start_up_view_modal_appear(self, timeout=10):
        try:
            self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)
            return True
        except TimeoutException:
            logging.warning('start up view window is not exist')
            return False

    def close(self, timeout=10):
        self._tool.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)


class WebElementManagerReloadModal(ConfirmationModal):
    _RELOAD_MODAL_XPATH = '//div[@class="modal-content"]//*[contains(@title, "Web Element Manager Reload Recommended")]'
    _RELOAD_BUTTON_XPATH = "//div[@class='modal-content']//button[contains(text(), 'Reload')]"

    def __init__(self, tool):
        super(WebElementManagerReloadModal, self).__init__(tool)

    def wait_for_web_element_manager_reload_modal_appear(self, timeout=10):
        try:
            self.wait_until_modal_appear((By.XPATH, self._RELOAD_MODAL_XPATH), timeout)
            return True
        except TimeoutException:
            logging.warning('web element manager reload window is not exist')
            return False

    def reload(self, timeout=60):
        self._tool.click_enabled_element((By.XPATH, self._RELOAD_BUTTON_XPATH), timeout)
